import { useState, type ReactNode } from 'react'

import { useNavigate } from 'react-router-dom'

import { Box, CircularProgress } from '@mui/material'

import { createTrainingPlan, findOverlappingFmPlans, isUniqueViolation } from '@/api/trainingPlans'
import { useAuth } from '@/contexts/AuthContext'
import { useTypedSearchParams } from '@/hooks/useTypedSearchParams'
import { useFmCount } from '@/pages/flash-man/hooks/useGetContent'
import { routes } from '@/routes'

import {
  PlanForm,
  PlanPathOverlapMessage,
  formDataToPlanInsert,
  type PlanFormData,
} from '../components'

export function PlansNewPage() {
  const navigate = useNavigate()
  const { user } = useAuth()
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<ReactNode | null>(null)

  // flash-man 폴더에서 진입하면 ?owner&repo&path 로 fm:// 단위와 카드 파일 수를 미리 채운다.
  // 계획 이름은 PlanForm 이 마지막으로 고른 형식으로 채운다.
  const { queryParams } = useTypedSearchParams(routes.plans.new.$config)
  const { owner, repo, path } = queryParams
  const fmIdentifier = owner && repo ? { owner, repo, path } : undefined
  const { isLoading: isLoadingCount, data: fmFileCount } = useFmCount(fmIdentifier)
  const initialData = fmIdentifier
    ? {
        unitName: `fm://${owner}/${repo}${path ? '/' + path : ''}`,
        totalAmount: fmFileCount ?? undefined,
      }
    : undefined

  async function handleSubmit(data: PlanFormData) {
    if (!data.name.trim()) {
      setError('계획 이름을 입력해주세요.')
      return
    }
    if (!data.unitName.trim()) {
      setError('훈련 단위를 입력해주세요.')
      return
    }
    if (data.scheduleType === 'weekly' && data.scheduleDays.length === 0) {
      setError('훈련 요일을 선택해주세요.')
      return
    }

    try {
      setLoading(true)
      setError(null)

      // 한 fm:// 폴더에 플랜 하나. DB 제약(018)에 걸리기 전에 안내한다.
      const [overlapping] = await findOverlappingFmPlans(user!.id, data.unitName)
      if (overlapping) {
        setError(<PlanPathOverlapMessage plan={overlapping} />)
        return
      }

      await createTrainingPlan(formDataToPlanInsert(data, user!.id))
      goBack()
    } catch (err) {
      // 사전 검사와 INSERT 사이의 경합, 또는 검사 조회 실패 시 DB 제약이 잡아준다.
      setError(
        isUniqueViolation(err)
          ? '같은 폴더를 가리키는 계획이 이미 있습니다. 기존 계획을 재사용해 주세요.'
          : '계획 생성에 실패했습니다.'
      )
      // eslint-disable-next-line no-console
      console.error(err)
    } finally {
      setLoading(false)
    }
  }

  /**
   * 이전 페이지(예: flash-man 폴더 목록)로 돌아간다. URL 직접 진입처럼 앱 내 이전 기록이 없으면 계획 목록으로.
   * react-router 는 history.state.idx 에 앱 내 이동 순번을 기록한다.
   */
  function goBack() {
    if ((window.history.state as { idx?: number } | null)?.idx) {
      navigate(-1)
    } else {
      navigate(routes.plans.$())
    }
  }

  function handleCancel() {
    goBack()
  }

  // PlanForm 은 initialData 를 마운트 시점에만 읽으므로 파일 수 조회가 끝난 뒤 렌더링한다.
  if (fmIdentifier && isLoadingCount) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', py: 4 }}>
        <CircularProgress />
      </Box>
    )
  }

  return (
    <PlanForm
      initialData={initialData}
      onSubmit={handleSubmit}
      onCancel={handleCancel}
      loading={loading}
      error={error}
      title="새 훈련 계획"
      submitLabel="계획 생성"
      loadingLabel="생성 중..."
    />
  )
}
